package __PACKAGE__;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.neoforge.registries.RegisterEvent;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;

/**
 * Registers the particle type of Sparkle ("__MODID__:sparkle") on the NeoForge mod bus, without any change to the main class of the mod.
 * NeoForge 1.21.4 and later: the bus is found from the event (this file replaces the one of neoforge).
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
@EventBusSubscriber(modid = SparkleConfig.MOD_ID)
public final class SparkleNeoForge {
    private SparkleNeoForge() {
    }

    @SubscribeEvent
    public static void register(RegisterEvent event) {
        event.register(Registries.PARTICLE_TYPE, helper -> helper.register(ResourceLocation.tryParse(SparkleConfig.MOD_ID + ":" + Sparkle.TYPE_NAME), Sparkle.TYPE));
    }
}
